insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A suspensão condicional não se estende às penas restritivas de direitos nem à multa.', '["Suspensão não alcança restritivas de direitos.","Suspensão não alcança multa."]'::jsonb, '["O sursis suspende só a pena privativa de liberdade."]'::jsonb, 'Mesmo com a prisão suspensa, a multa aplicada continua a ser exigível.', '["Assertiva que estende o sursis à multa erra: o art. 80 afasta."]'::jsonb, '[]'::jsonb, '["Art. 77"]'::jsonb, 'under_review', 'claude'
