insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Expirado o prazo da suspensão sem que tenha havido revogação, considera-se extinta a pena privativa de liberdade.', '["Fim do prazo sem revogação: pena privativa de liberdade extinta."]'::jsonb, '["A extinção ocorre ao fim do período de prova sem revogação."]'::jsonb, 'Cumpridas as condições durante todo o prazo, a pena suspensa é declarada extinta.', '["Assertiva que determina cumprimento da pena após o prazo sem revogação erra: a pena fica extinta."]'::jsonb, '[]'::jsonb, '["Arts. 77 a 81"]'::jsonb, 'under_review', 'claude'
