insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Livramento condicional: o juiz pode conceder ao condenado a pena privativa de liberdade igual ou superior a 2 anos, desde que: cumprida mais de um terço da pena (não reincidente em crime doloso e com bons antecedentes) ou mais da metade (reincidente em crime doloso); comprovados bom comportamento, ausência de falta grave nos últimos 12 meses, bom desempenho no trabalho e aptidão para prover a própria subsistência; reparado o dano, salvo impossibilidade; e, para os crimes de maior gravidade (hediondo, tortura, tráfico, tráfico de pessoas e terrorismo), cumpridos mais de dois terços se o apenado não for reincidente específico (confira o texto completo, que traz outros incisos e o parágrafo único).', '["Pena igual ou superior a 2 anos.","I – mais de 1/3 se não reincidente em crime doloso e com bons antecedentes.","II – mais da metade se reincidente em crime doloso.","III – comprovação de bom comportamento, ausência de falta grave nos últimos 12 meses, bom desempenho no trabalho e aptidão para subsistência por trabalho honesto.","IV – dano reparado, salvo efetiva impossibilidade.","V – mais de 2/3 nos crimes hediondos, tortura, tráfico de drogas, tráfico de pessoas e terrorismo, se não reincidente específico."]'::jsonb, '["Frações: mais de 1/3 (primário com bons antecedentes), mais da metade (reincidente doloso), mais de 2/3 (hediondos e equiparados, não reincidente específico).","Falta grave: considera-se os últimos 12 meses."]'::jsonb, 'Condenado primário e de bons antecedentes a 6 anos pode pedir livramento condicional após cumprir mais de 2 anos, se cumpridos os demais requisitos.', '["Assertiva que exige cumprimento de mais da metade da pena do primário com bons antecedentes erra: basta mais de um terço."]'::jsonb, '[{"termo":"Livramento condicional","significado":"Liberdade antecipada do condenado, mediante condições, após cumprir parte da pena."}]'::jsonb, '["Arts. 84 a 90"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-83'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As penas que correspondem a infrações diversas devem somar-se para efeito do livramento condicional.', '["Para o livramento, somam-se as penas de infrações diversas."]'::jsonb, '["A soma vale para calcular a pena cumprida e o requisito temporal."]'::jsonb, 'Duas condenações são somadas para verificar se o tempo mínimo exigido foi cumprido.', '["Assertiva que avalia cada condenação isoladamente para o livramento condicional contraria o art. 84."]'::jsonb, '[]'::jsonb, '["Art. 83"]'::jsonb, 'under_review', 'claude'
