insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A sentença do livramento especificará as condições a que fica subordinado o benefício.', '["Condições do livramento especificadas na sentença."]'::jsonb, '["As condições devem constar da decisão que concede o livramento."]'::jsonb, 'A decisão fixa obrigações como comparecer periodicamente em juízo.', '["Assertiva que dispensa especificar condições no livramento contraria o art. 85."]'::jsonb, '[]'::jsonb, '["Art. 83"]'::jsonb, 'under_review', 'claude'
