insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Revogação facultativa: o juiz pode revogar o livramento se o liberado deixar de cumprir qualquer das obrigações da sentença, ou for irrecorrivelmente condenado, por crime ou contravenção, a pena que não seja privativa de liberdade.', '["Descumprimento de obrigação da sentença.","Condenação irrecorrível, por crime ou contravenção, a pena não privativa de liberdade."]'::jsonb, '["Aqui o juiz PODE revogar (facultativa)."]'::jsonb, 'O liberado deixa de comparecer a juízo sem justificativa: o juiz pode revogar o livramento.', '["Assertiva que trata como obrigatória a revogação do art. 87 erra: é facultativa."]'::jsonb, '[]'::jsonb, '["Art. 86"]'::jsonb, 'under_review', 'claude'
