insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Efeitos da revogação: revogado o livramento, não poderá ser novamente concedido, e, salvo quando a revogação resulta de condenação por outro crime anterior àquele benefício, não se desconta na pena o tempo em que esteve solto o condenado.', '["Revogado, não pode ser concedido de novo.","Em regra, o tempo solto não é descontado da pena.","Exceção: revogação por condenação por crime anterior ao benefício."]'::jsonb, '["A exceção do desconto é a revogação por crime ANTERIOR ao livramento."]'::jsonb, 'Revogado o livramento por novo crime, o tempo em que o condenado esteve solto não é descontado.', '["Assertiva que permite novo livramento após a revogação contraria o art. 88."]'::jsonb, '[]'::jsonb, '["Arts. 86 e 87"]'::jsonb, 'under_review', 'claude'
